# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">MUSTAFA KEMAL\'İN KAĞNISI VE ŞİİRDE AHENK UNSURLARI (T.D.7.2 / T.O.7.18)</text>\n  <rect x="28" y="48" width="310" height="190" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="183" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">1. Mustafa Kemal\'in Kağnısı (Epik Şiir)</text>\n  <text x="44" y="98" font-size="11" fill="#334155">• Şair: Fazıl Hüsnü Dağlarca</text>\n  <text x="44" y="118" font-size="11" fill="#334155">• Kahraman: Cepheye kağnısıyla mermi</text>\n  <text x="44" y="134" font-size="11" fill="#334155">  taşıyan fedakâr Anadolu kadını ELİF</text>\n  <text x="44" y="156" font-size="11" fill="#334155">• Olay: Öküzü KOCABAŞ\'ın yorgunluktan</text>\n  <text x="44" y="172" font-size="11" fill="#334155">  çökmesi üzerine Elif\'in Kocabaş\'ın</text>\n  <text x="44" y="188" font-size="11" fill="#334155">  yerine boyunduruğa girip kağnıyı çekmesi</text>\n  <text x="183" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#991b1b">Tema: Vatanseverlik ve Fedakârlık</text>\n  <rect x="362" y="48" width="310" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">2. Şiirde Biçim, Ahenk ve Söz Sanatları</text>\n  <text x="378" y="98" font-size="11" fill="#334155">• Nazım Birimi: Dize (mısra), beyit, dörtlük</text>\n  <text x="378" y="120" font-size="11" fill="#334155">• Ölçü: Hece ölçüsü (dizedeki hece eşitliği)</text>\n  <text x="378" y="142" font-size="11" fill="#334155">• Redif: Dize sonlarında görevleri ve</text>\n  <text x="378" y="158" font-size="11" fill="#334155">  yazılışları aynı olan ek/kelime tekrarları</text>\n  <text x="378" y="180" font-size="11" fill="#334155">• Kafiye (Uyak): Görevleri farklı ses benzerliği</text>\n  <text x="378" y="202" font-size="11" fill="#334155">• Söz Sanatları: Benzetme, Kişileştirme,</text>\n  <text x="378" y="218" font-size="11" fill="#334155">  Konuşturma, Abartma (Mübalağa), Tezat</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">FİİLLERDE KİP, KİŞİ VE ANLAM (ZAMAN) KAYMASI ÖZETİ</text>\n  <rect x="25" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="130" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">1. Haber (Bildirme) Kipleri</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• Bilinen Geçmiş: -dı / -di / -tı</text>\n  <text x="40" y="120" font-size="11" fill="#334155">• Duyulan Geçmiş: -mış / -miş</text>\n  <text x="40" y="142" font-size="11" fill="#334155">• Şimdiki Zaman: -yor (-makta)</text>\n  <text x="40" y="164" font-size="11" fill="#334155">• Gelecek Zaman: -ecek / -acak</text>\n  <text x="40" y="186" font-size="11" fill="#334155">• Geniş Zaman: -r / -ar / -er</text>\n  <text x="130" y="218" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1e40af">(Zaman anlamı taşırlar)</text>\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">2. Dilek (Tasarlama) Kipleri</text>\n  <text x="260" y="98" font-size="11" fill="#334155">• Gereklilik Kipi: -meli / -malı</text>\n  <text x="260" y="122" font-size="11" fill="#334155">• Dilek-Şart Kipi: -se / -sa</text>\n  <text x="260" y="146" font-size="11" fill="#334155">• İstek Kipi: -e / -a</text>\n  <text x="260" y="170" font-size="11" fill="#334155">• Emir Kipi: (Kip eki yoktur,</text>\n  <text x="260" y="188" font-size="11" fill="#334155">  kişi ekleriyle çekimlenir)</text>\n  <text x="350" y="218" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#166534">(Zaman değil, dilek bildirirler)</text>\n  <rect x="465" y="48" width="210" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="570" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#a16207">3. Fiilde Anlam Kayması</text>\n  <text x="480" y="98" font-size="11" fill="#334155">• Bir kip ekinin başka bir kipin</text>\n  <text x="480" y="114" font-size="11" fill="#334155">  yerine kullanılmasıdır:</text>\n  <text x="480" y="138" font-size="10.5" fill="#334155">• "Yarın Ankara\'ya gidiyorum"</text>\n  <text x="480" y="154" font-size="10.5" fill="#92400e">  (-yor → gideceğim / gelecek)</text>\n  <text x="480" y="178" font-size="10.5" fill="#334155">• "Her sabah erken kalkıyor"</text>\n  <text x="480" y="194" font-size="10.5" fill="#92400e">  (-yor → kalkar / geniş zaman)</text>\n  <text x="570" y="220" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#78350f">Anlatım bozukluğu DEĞİLDİR!</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">EK-FİİL (BİRLEŞİK ÇEKİMLİ FİİLLER) VE YAPI ÖZETİ</text>\n  <rect x="28" y="48" width="310" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="183" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. Birleşik Zamanlı (Çekimli) Fiiller</text>\n  <text x="44" y="96" font-size="11" font-weight="bold" fill="#1e40af">Formül: Fiil + 1. Kip Eki + Ek-Fiil (idi/imiş/ise)</text>\n  <text x="44" y="122" font-size="11" fill="#334155">• Hikâye Birleşik Zaman (idi → -dı/-di):</text>\n  <text x="44" y="138" font-size="10.5" fill="#475569">  gel-iyor-du (Şimdiki zamanın hikâyesi)</text>\n  <text x="44" y="162" font-size="11" fill="#334155">• Rivayet Birleşik Zaman (imiş → -mış/-miş):</text>\n  <text x="44" y="178" font-size="10.5" fill="#475569">  oku-yacak-mış (Gelecek zamanın rivayeti)</text>\n  <text x="44" y="202" font-size="11" fill="#334155">• Şart Birleşik Zaman (ise → -sa/-se):</text>\n  <text x="44" y="218" font-size="10.5" fill="#475569">  çalış-ır-sa (Geniş zamanın şartı)</text>\n  <rect x="362" y="48" width="310" height="190" rx="8" fill="#fdf2f8" stroke="#ec4899"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">2. Yapısına Göre Fiiller (Tema Özeti)</text>\n  <text x="378" y="98" font-size="11" fill="#334155">• Basit Fiil: Yapım eki almamış (koş-tu)</text>\n  <text x="378" y="120" font-size="11" fill="#334155">• Türemiş Fiil: Yapım eki almış (baş-la-dı)</text>\n  <text x="378" y="142" font-size="11" fill="#334155">• Birleşik Yapılı Fiiller (3 Grup):</text>\n  <text x="378" y="160" font-size="10.5" fill="#475569">  1) Kurallı: -ebil (yeterlik), -ıver (tezlik),</text>\n  <text x="378" y="176" font-size="10.5" fill="#475569">     -edur/-ekal/-egel (sürerlik), -eyaz (yaklaşma)</text>\n  <text x="378" y="194" font-size="10.5" fill="#475569">  2) Yardımcı fiilli: et-, ol-, kıl-, eyle- (yardım et-)</text>\n  <text x="378" y="212" font-size="10.5" fill="#475569">  3) Anlamca kaynaşmış: kulak as-, vazgeç-</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
